import heapq
from collections import Counter


def top_ips(lines, k):
    counts = Counter()
    for line in lines:
        fields = line.split(None, 1)          # the first field is the client IP; a blank line gives []
        if fields:
            counts[fields[0]] += 1
    # a heap of at most k candidates instead of sorting every address; the key puts big counts first, then small IPs
    return heapq.nsmallest(k, counts.items(), key=lambda item: (-item[1], item[0]))
